-- ── 1 · The checkpoint set is a version of its own. ────────────────────────
-- Beside LAB_DICTATION and S4B_COLUMNS, never replacing them: batches reference those maps and
-- a lab result points at the checkpoint it was taken against.

do $$
begin
  if not exists (select 1 from pg_enum e join pg_type t on t.oid = e.enumtypid
                 where t.typname = 'lab_checkpoint_map' and e.enumlabel = 'LAB_2026A') then
    alter type public.lab_checkpoint_map add value 'LAB_2026A';
  end if;
end $$;


-- ── 2 · What a checkpoint is, beyond its parameters. ───────────────────────
-- `kind` is the whole of LAB-2026A's gate model: a GATE stops production until approved, a
-- DECISION branches the process, a RECORD is evidence and nothing else. It was nowhere in the
-- schema, so no engine could tell them apart.

alter table public.lab_checkpoint
  add column if not exists kind           text not null default 'RECORD',
  add column if not exists evidence_kinds text[] not null default array[]::text[],
  add column if not exists per_pile       boolean not null default false,
  add column if not exists stage          text,
  add column if not exists where_note     text,
  add column if not exists guidance       text,
  add column if not exists sort_order     int,
  add column if not exists confidence     text;

alter table public.lab_checkpoint drop constraint if exists lab_checkpoint_kind_known;
alter table public.lab_checkpoint add constraint lab_checkpoint_kind_known check (
  kind in ('GATE', 'DECISION', 'RECORD'));

comment on column public.lab_checkpoint.kind is
  'GATE stops production until an APPROVED result exists. DECISION branches the process. '
  'RECORD is evidence. LAB-2026A: 4 gates, 1 decision, 20 records. 0052.';

comment on column public.lab_checkpoint.evidence_kinds is
  'The checkpoint-specific evidence LAB-2026A asks for — LOT_PHOTO, WEIGHMENT_SLIP, '
  'SAMPLE_PHOTO, BEFORE_PHOTO, HEIGHT_PHOTO, TUNNEL_PHOTO, AFTER_PHOTO. Not one generic '
  'upload: a weighment slip and a height photo answer different questions. 0052.';


