-- ── 5 · Which activity carries which checkpoint. ───────────────────────────
-- The join 0053 needs to bind a gate, and the join a client needs to render a checkpoint form
-- from its definition rather than from twenty-five hand-written screens.

create table if not exists public.lab_checkpoint_activity (
  checkpoint_map      public.lab_checkpoint_map not null,
  checkpoint_code     text not null,
  process_activity_id uuid not null references public.process_activity(id) on delete cascade,
  gates_activity_code text,
  primary key (checkpoint_map, checkpoint_code, process_activity_id)
);

comment on table public.lab_checkpoint_activity is
  'Which planned activity carries which laboratory checkpoint, and — for a GATE — which '
  'PRODUCTION activity it holds. lab_checkpoints.json supplies blocks_activity_code as null on '
  'purpose: real activity codes are read from process_activity, never invented. 0052.';

alter table public.lab_checkpoint_activity enable row level security;
drop policy if exists lab_checkpoint_activity_read on public.lab_checkpoint_activity;
create policy lab_checkpoint_activity_read on public.lab_checkpoint_activity
  for select to authenticated using (true);
grant select on public.lab_checkpoint_activity to authenticated;

