-- ── 6 · Checkpoint-specific evidence. ──────────────────────────────────────
-- LAB-2026A asks for seven distinct kinds and the difference matters: a HEIGHT_PHOTO proves the
-- measurement that sets the reload height, and a WEIGHMENT_SLIP is a document. Collapsing them
-- into one "upload image" would lose the question each was answering.

with pd as (select id from public.process_definition where code = 'PROCESS-2026C' and version = 1)
insert into public.evidence_requirement
  (process_activity_id, key, label, media_kinds, min_count, is_required, gates_submission,
   capture_hint, ordering)
select pa.id, e.key, e.label, array['photo']::text[], 1, true, true, e.hint, e.ord
from pd
join (values
  ('LAB-RM-01', 'LOT_PHOTO', 'Lot photograph', 'Photograph the incoming lot as received.', 10),
