-- ── 7 · Published again, and the envelope must not have moved. ─────────────

update public.process_definition
   set status = 'published', published_at = coalesce(published_at, now())
 where code = 'PROCESS-2026C' and version = 1;

do $$
declare s record;
begin
  select * into s from public.v_process_envelope where code = 'PROCESS-2026C';
  if s.envelope_disagrees then
    raise exception
      'Seeding the laboratory moved PROCESS-2026C''s standard: its activities now compute %h against a stated envelope of %h. Laboratory work is parallel and must contribute no wall clock — check that every lab activity is PARALLEL_NO_WALLCLOCK.',
      s.calculated_standard_hr, s.stated_envelope_hr;
  end if;
end $$;
